absl::string_view GetRomanTablePreset(absl::string_view id) {
  if (id == "simplified_azik") return absl::string_view(kSimplifiedAzik);
  if (id == "shingetsu") return absl::string_view(kShingetsu);
  if (id == "seoto") return absl::string_view(kSeoto);
  if (id == "seoto_plus") return absl::string_view(kSeotoPlus);
  return {};
}

absl::string_view ResolveRomanTablePreset(const Config& config,
                                         absl::string_view id) {
  const absl::string_view builtin = GetRomanTablePreset(id);
  if (!builtin.empty()) return builtin;
  if (!id.starts_with("user:")) return {};
  const absl::string_view local_id = id.substr(5);
  for (const auto &preset : config.user_roman_table_presets()) {
    if (absl::string_view(preset.id()) == local_id && !preset.table().empty() &&
        preset.table().size() <= 64 * 1024) return preset.table();
  }
  return {};
}

void NormalizeRomanTablePreset(Config* config) {
  if (config->roman_table_preset_id().empty()) {
    config->clear_roman_table_preset_snapshot_hash();
    return;
  }
  const absl::string_view latest =
      ResolveRomanTablePreset(*config, config->roman_table_preset_id());
  const bool matches_snapshot =
      config->has_roman_table_preset_snapshot_hash() &&
      config->roman_table_preset_snapshot_hash() ==
          CityFingerprint(config->custom_roman_table());
  if (latest.empty() || !matches_snapshot) {
    // An unknown/removed preset or externally edited table becomes custom.
    // Never overwrite data that has been changed outside the editor.
    config->clear_roman_table_preset_id();
    config->clear_roman_table_preset_snapshot_hash();
    return;
  }
  if (absl::string_view(config->custom_roman_table()) != latest) {
    config->set_custom_roman_table(std::string(latest.data(), latest.size()));
  }
  config->set_roman_table_preset_snapshot_hash(
      CityFingerprint(config->custom_roman_table()));
}

